const validHex=value=>/^#[0-9a-fA-F]{6}$/.test(String(value||''));
function registerCustomBelt(raw,{persistLocal=true}={}){
 const id=cleanString(raw?.id||raw?.name).slice(0,100), existing=beltOf(id);
 if(!id)return null;
 if(existing&&!existing.custom)return existing;
 const swatches=(Array.isArray(raw?.swatches)?raw.swatches:[]).filter(validHex).slice(0,2);
 const belt={id,swatches:swatches.length?swatches:['#6b7f95'],kyu:raw?.kyu===null||raw?.kyu===undefined||raw?.kyu===''?null:String(raw.kyu).slice(0,40),custom:true};
 if(existing){Object.assign(existing,belt)}else BELTS.push(belt);
 if(!state.layouts[id])state.layouts[id]=deep(DEFAULT_FIELDS);
 if(persistLocal)persist();
 return beltOf(id);
}
