function candidateFingerprint(list=state.candidates){return JSON.stringify(list.filter(candidate=>!candidate.demo).map(candidate=>({...candidate,serial:officialSerial(candidate.serial)||officialSerial(candidate.ordinal)})))}
function candidateRecordFingerprint(candidate){return JSON.stringify({...candidate,serial:officialSerial(candidate.serial)||officialSerial(candidate.ordinal),status:candidateErrors(candidate).length?'incomplete':'ready'})}
function templateConfig(beltId,fields=state.layouts[beltId]||[],backgroundUrl=state.templates[beltId]?.remoteUrl||''){return {version:2,belt:beltId,beltMeta:customBeltMetadata(beltId),size:{width:W,height:H},fields,backgroundUrl}}
function templateFingerprint(config={}){return JSON.stringify({version:2,belt:config.belt||'',beltMeta:config.beltMeta||null,size:{width:Number(config.size?.width||W),height:Number(config.size?.height||H)},fields:Array.isArray(config.fields)?config.fields:[],backgroundUrl:config.backgroundUrl||''})}

function setupBackendRealtime(){if(!backendClient||backendRealtimeChannel)return;const refresh=(reason='realtime')=>{if(backendSyncBusy||backendDirty||Date.now()<backendRealtimeSuppressUntil)return;clearTimeout(backendRealtimeTimer);backendRealtimeTimer=setTimeout(()=>{if(!backendSyncBusy&&!backendDirty){debugLog('Automatic refresh', {reason});loadBackendData({checkHealth:false,reason})}},900)};backendRealtimeChannel=backendClient.channel('budo-main-realtime').on('postgres_changes',{event:'*',schema:'public',table:'candidates'},()=>refresh('realtime:candidates')).on('postgres_changes',{event:'*',schema:'public',table:'template_presets'},()=>refresh('realtime:presets')).on('postgres_changes',{event:'*',schema:'public',table:'template_assets'},()=>refresh('realtime:assets')).subscribe(status=>{if(status==='CHANNEL_ERROR')backendUi('Realtime indisponible','Vérifiez la publication Supabase',true)});window.addEventListener('focus',()=>refresh('window:focus'));if(!backendRefreshTimer)backendRefreshTimer=setInterval(()=>{if(!document.hidden&&!backendSyncBusy&&!backendDirty)refresh('interval')},60000)}

function backendAuthHeaders(){return backendSession?.access_token?{Authorization:`Bearer ${backendSession.access_token}`}:{}}
async function backendRequest(path,options={}){const headers={...backendAuthHeaders(),...(options.headers||{})};if(options.body&&!(options.body instanceof FormData))headers['Content-Type']='application/json';const response=await fetch(`${BACKEND_API}${path}`,{...options,headers});const raw=await response.text();let data={};try{data=raw?JSON.parse(raw):{}}catch{data={error:raw}}if(!response.ok){const error=Error(data.error||`Backend request failed (${response.status})`);error.status=response.status;throw error}return data}
function backendUi(status,detail='',error=false){const root=$('#backend-tools'),label=$('#backend-status'),small=$('#backend-status-detail'),gate=$('#backend-gate'),gateStatus=$('#backend-gate-status'),gateDetail=$('#backend-gate-detail');if(label)label.textContent=status;if(small)small.textContent=detail;if(root)root.classList.toggle('error',error),root.classList.toggle('connected',!error&&backendReady);if(gate){gate.hidden=backendReady;gate.setAttribute('aria-busy',String(!backendReady));gateStatus.textContent=backendReady?'Services connectés':(error?'Connexion indisponible':status);gateDetail.textContent=backendReady?'Supabase · Cloudinary · Gemini':(detail||'Le studio reste verrouillé tant que les services ne sont pas disponibles.')}document.body.classList.toggle('backend-locked',!backendReady);const text=backendSession?'Déconnexion':'Connexion';const login=$('#btn-backend-login'),headerLogin=$('#btn-header-login'),authState=$('#auth-state');if(login)login.textContent=text;if(headerLogin){headerLogin.textContent=text;headerLogin.classList.toggle('logged-in',Boolean(backendSession));}if(authState){authState.textContent=backendSession?.user?.email||'Mode public';authState.classList.toggle('authenticated',Boolean(backendSession));}}
function returnToLogin(reason='Votre session a expiré. Connectez-vous à nouveau.'){backendReady=false;backendApiReady=false;backendUi('Session requise',reason,true);window.dispatchEvent(new CustomEvent('budo:auth-state',{detail:{session:null}}))}
function showBackendLogin(){openModal(`<div class="modal-head"><div><h2>Connexion BUDO Studio</h2><p>Connectez-vous pour synchroniser les candidats, modèles et services IA.</p></div><button class="modal-x">×</button></div><form id="backend-login-form"><label class="property-label">Email<input id="backend-email" type="email" required autocomplete="email"></label><label class="property-label">Mot de passe<input id="backend-password" type="password" required autocomplete="current-password"></label><div id="backend-login-error" class="modal-alert" hidden></div><div class="modal-footer"><button type="button" class="btn secondary" id="backend-login-cancel">Annuler</button><button class="btn primary" type="submit">Se connecter</button></div></form>`);$('#backend-login-cancel').onclick=closeModal;$('#backend-login-form').onsubmit=async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button[type="submit"]');button.disabled=true;try{const {data,error}=await backendClient.auth.signInWithPassword({email:$('#backend-email').value.trim(),password:$('#backend-password').value});if(error)throw error;backendSession=data.session;closeModal();await loadBackendData();showToast('Connexion réussie — données synchronisées')}catch(error){const node=$('#backend-login-error');node.hidden=false;node.textContent=error.message}finally{button.disabled=false}}}
async function loadBackendData({checkHealth=true,reason='initial'}={}){
 const loadToken=++backendLoadToken;
 setupBackendRealtime();
 debugLog('Backend load started', {reason,authenticated:Boolean(backendSession)});
 try{
  const localCandidates=[...state.candidates];
  const health=checkHealth?await backendRequest('/health'):{schemaReady:true};
  backendApiReady=true;
  if(!health.schemaReady){backendReady=false;backendUi('Schéma Supabase manquant',health.schemaError||'Exécutez supabase/schema.sql.',true);return}
  const missingServices=[!health.cloudinary?'Cloudinary':'',!health.gemini?'Gemini':''].filter(Boolean);if(missingServices.length){backendReady=false;backendApiReady=false;backendUi('Services requis indisponibles',`Configurez : ${missingServices.join(' · ')}`,true);return}
  const [candidateData,presets,assets]=await Promise.all([backendRequest('/candidates?pageSize=4000'),backendRequest('/templates/presets'),backendRequest('/templates/assets')]);
  if(loadToken!==backendLoadToken||backendSyncBusy)return;
  const remoteCandidates=candidateData.data||[];
  const migrateLocal=!remoteCandidates.length&&!presets.length&&!assets.length&&localCandidates.some(candidate=>!candidate.demo);
  const remoteCustomIds=new Set(presets.filter(preset=>preset.config?.beltMeta?.id).map(preset=>preset.config.beltMeta.id));
  const migrateLocalTemplates=BELTS.some(belt=>belt.custom&&!remoteCustomIds.has(belt.id));
  debugLog('Backend load', {remoteCandidates:remoteCandidates.length,localCandidates:localCandidates.length,presets:presets.length,assets:assets.length,migrateLocal,migrateLocalTemplates});
  state.candidates=migrateLocal?localCandidates:remoteCandidates;
  backendCandidateIds.clear();backendCandidateFingerprints.clear();remoteCandidates.forEach(candidate=>{backendCandidateIds.add(candidate.id);backendCandidateFingerprints.set(candidate.id,candidateRecordFingerprint(candidate));});
  backendPresetIds.clear();backendPresetFingerprints.clear();
  for(const preset of presets){
   const meta=preset.config?.beltMeta;
   if(meta?.id)registerCustomBelt(meta,{persistLocal:false});
   if(preset.belt){backendPresetIds.set(preset.belt,preset.id);backendPresetFingerprints.set(preset.belt,templateFingerprint(preset.config||{}));}
   if(preset.belt&&Array.isArray(preset.config?.fields))state.layouts[preset.belt]=preset.config.fields.map(field=>({...deep(DEFAULT_FIELDS[0]),...field}));
  }
  for(const asset of assets){if(asset.belt)state.templates[asset.belt]={name:asset.name,src:asset.previewUrl||asset.url,remoteUrl:asset.url,cloudinary:true};}
  backendReady=true;backendUi('Services connectés','Supabase · Cloudinary · Gemini');
  renderStats();renderCandidates();renderBeltSelectors();renderEditor();renderTemplateList();
  if(!migrateLocal)backendCandidateFingerprint=candidateFingerprint(state.candidates);
  if(migrateLocal||migrateLocalTemplates)await syncBackend();
  debugLog('Backend load completed', {reason,candidates:state.candidates.length,presets:presets.length,assets:assets.length,migrateLocal,migrateLocalTemplates});
 }catch(error){if(error.status===401){returnToLogin('Votre session Supabase est absente ou expirée.');return}backendReady=false;backendApiReady=false;backendUi('Connexion backend impossible',error.message,true);showToast(error.message,true)}
}
async function syncBackend(){
 if(!backendReady||backendSyncBusy)return;
 backendLoadToken++;
 backendSyncBusy=true;
 try{
  const layoutSnapshot=Object.fromEntries(BELTS.map(belt=>[belt.id,deep(state.layouts[belt.id]||[])]));
  const candidateChanged=candidateFingerprint(state.candidates)!==backendCandidateFingerprint;
  if(candidateChanged){
  state.candidates=state.candidates.map(candidate=>({...candidate,serial:officialSerial(candidate.serial)||officialSerial(candidate.ordinal)})).filter(candidate=>!backendDeletedCandidateIds.has(candidate.id));
   for(const candidate of [...state.candidates]){
    if(candidate.demo||backendDeletedCandidateIds.has(candidate.id))continue;
    const payload={...candidate,status:candidateErrors(candidate).length?'incomplete':'ready'};
    if(backendCandidateIds.has(candidate.id)&&backendCandidateFingerprints.get(candidate.id)===candidateRecordFingerprint(candidate))continue;
    if(backendCandidateIds.has(candidate.id))await backendRequest(`/candidates/${candidate.id}`,{method:'PUT',body:JSON.stringify(payload)});
    else{const saved=await backendRequest('/candidates',{method:'POST',body:JSON.stringify(payload)});if(backendDeletedCandidateIds.has(candidate.id)){await backendRequest(`/candidates/${saved.id}`,{method:'DELETE'});continue}const index=state.candidates.findIndex(item=>item.id===candidate.id);if(index>=0){state.candidates[index]={...state.candidates[index],id:saved.id};state.selectedIds.delete(candidate.id);if(state.selectedIds.has(saved.id))state.selectedIds.add(saved.id)}backendCandidateIds.add(saved.id);backendCandidateFingerprints.set(saved.id,candidateRecordFingerprint({...candidate,id:saved.id}))}
    if(backendCandidateIds.has(candidate.id))backendCandidateFingerprints.set(candidate.id,candidateRecordFingerprint(candidate));
   }
   const currentIds=new Set(state.candidates.filter(candidate=>!candidate.demo).map(candidate=>candidate.id));
   for(const id of [...backendCandidateIds])if(!currentIds.has(id)){await backendRequest(`/candidates/${id}`,{method:'DELETE'});backendCandidateIds.delete(id);backendCandidateFingerprints.delete(id)}
   backendCandidateFingerprint=candidateFingerprint(state.candidates);
  }
  for(const belt of BELTS){
   const beltId=belt.id,config=templateConfig(beltId,layoutSnapshot[beltId],state.templates[beltId]?.remoteUrl||''),fingerprint=templateFingerprint(config);
   const existingId=backendPresetIds.get(beltId);
   if(existingId&&backendPresetFingerprints.get(beltId)===fingerprint){debugLog('Template unchanged', {belt:beltId});continue}
   const saved=await backendRequest(existingId?`/templates/presets/${existingId}`:'/templates/presets',{method:existingId?'PUT':'POST',body:JSON.stringify({name:`${beltId} certificate template`,belt:beltId,description:'Main BUDO Studio editor configuration',config})});
   backendPresetIds.set(beltId,saved.id);
   backendPresetFingerprints.set(beltId,templateFingerprint(saved.config||config));
   debugLog('Template saved', {belt:beltId,presetId:saved.id,fieldCount:config.fields.length});
  }
  backendRealtimeSuppressUntil=Date.now()+1500;
  backendDirty=false;
  $('#save-state').textContent='Enregistré dans Supabase';
  debugLog('Backend sync completed', {candidates:state.candidates.length,presets:backendPresetIds.size});
 }catch(error){backendUi('Synchronisation échouée',error.message,true)}finally{backendSyncBusy=false}
}
function scheduleBackendSync(){if(!backendReady)return;clearTimeout(backendSyncTimer);backendSyncTimer=setTimeout(()=>syncBackend(),300)}
async function initBackend(){if(!window.BUDO_PUBLIC_CONFIG){backendUi('Configuration Supabase manquante','Rechargez après avoir configuré Supabase.',true);return}backendClient=window.BudoAuthClient||window.supabase?.createClient?.(window.BUDO_PUBLIC_CONFIG.supabaseUrl,window.BUDO_PUBLIC_CONFIG.supabasePublishableKey);if(!backendClient){backendUi('Client Supabase indisponible','Le navigateur n’a pas chargé le client d’authentification.',true);return}let session=null;for(let attempt=0;attempt<6&&!session;attempt++){const {data,error}=await backendClient.auth.getSession();if(error){returnToLogin('Impossible de vérifier votre session Supabase.');return}session=data.session;if(!session&&attempt<5)await new Promise(resolve=>setTimeout(resolve,250))}backendSession=session;if(!backendSession){returnToLogin('Connectez-vous pour ouvrir le studio.');return}await loadBackendData();backendClient.auth.onAuthStateChange((_event,nextSession)=>{if((nextSession?.access_token||'')===(backendSession?.access_token||''))return;backendSession=nextSession;if(nextSession)loadBackendData();else returnToLogin('Votre session Supabase est terminée.');})}
function tryLoadSettings(){
 try{const saved=JSON.parse(localStorage.getItem(LS_KEY)||localStorage.getItem('budo-studio-v2-settings')||'null');const customBelts=JSON.parse(localStorage.getItem(LS_CUSTOM_BELTS)||JSON.stringify(saved?.customBelts||[]));if(Array.isArray(customBelts))customBelts.forEach(belt=>registerCustomBelt(belt,{persistLocal:false}));if(saved?.layouts){
  for(const belt of BELTS)if(Array.isArray(saved.layouts[belt.id]))state.layouts[belt.id]=saved.layouts[belt.id].filter(f=>f&&f.id).map(f=>({...deep(DEFAULT_FIELDS.find(x=>x.id===f.id)||DEFAULT_FIELDS[0]),...f}));
  if(beltOf(saved.belt))state.belt=saved.belt;
  state.snap=saved.snap!==false;state.guides=saved.guides!==false;state.grid=Boolean(saved.grid);fabricPreferred=saved.fabricMode!==false;
 }
  const deleted=JSON.parse(localStorage.getItem(LS_DELETED_CANDIDATES)||'[]');if(Array.isArray(deleted))deleted.filter(Boolean).forEach(id=>backendDeletedCandidateIds.add(id));
  const savedC=JSON.parse(localStorage.getItem(LS_CANDIDATES)||localStorage.getItem('budo-studio-v2-candidates')||'null');if(Array.isArray(savedC))state.candidates=savedC.filter(c=>c&&c.id&&typeof c.name==='string'&&!backendDeletedCandidateIds.has(c.id)).slice(0,4000);const selected=JSON.parse(localStorage.getItem(LS_SELECTION)||'[]');if(Array.isArray(selected)){const ids=new Set(state.candidates.map(c=>c.id));state.selectedIds=new Set(selected.filter(id=>ids.has(id)));}
 }catch(err){console.warn('Configuration précédente ignorée :',err)}
}
function persist(){backendDirty=true;clearTimeout(saveTimer);$('#save-state').textContent='Enregistrement…';saveTimer=setTimeout(()=>{
  try{const customBelts=BELTS.filter(belt=>belt.custom).map(belt=>({id:belt.id,swatches:[...belt.swatches],kyu:belt.kyu,custom:true}));localStorage.setItem(LS_KEY,JSON.stringify({layouts:state.layouts,belt:state.belt,snap:state.snap,guides:state.guides,grid:state.grid,fabricMode:fabricPreferred,customBelts}));localStorage.setItem(LS_CUSTOM_BELTS,JSON.stringify(customBelts));localStorage.setItem(LS_CANDIDATES,JSON.stringify(state.candidates));localStorage.setItem(LS_SELECTION,JSON.stringify([...state.selectedIds]));localStorage.setItem(LS_DELETED_CANDIDATES,JSON.stringify([...backendDeletedCandidateIds]));$('#save-state').textContent='Enregistré sur cet appareil';}catch(e){$('#save-state').textContent='Stockage local saturé';console.warn(e)}
 },260);scheduleBackendSync()}
function showToast(message,error=false){const root=$('#toast-root');root.replaceChildren();const node=document.createElement('div');node.className=`toast${error?' error':''}`;node.innerHTML=`<span>${error?'⚠':'✓'} &nbsp; ${html(message)}</span><button class="close" aria-label="Fermer">×</button>`;root.append(node);node.querySelector('button').onclick=()=>node.remove();setTimeout(()=>node.remove(),5200)}
function setPage(page){if(!['editor','candidates','templates','overview'].includes(page))return;state.page=page;$$('.tab-view').forEach(v=>v.classList.toggle('hidden',v.id!==`view-${page}`));$$('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===page));const names={editor:['Éditeur de diplôme','Déplacez directement chaque zone sur le modèle, avec un aperçu fidèle en temps réel.'],candidates:['Gestion des candidats','Importez, contrôlez et corrigez les informations avant impression.'],templates:['Bibliothèque des modèles','Un modèle vierge et une mise en page indépendante pour chaque ceinture.'],overview:['Vue générale','De la liste Excel aux diplômes PDF, directement dans le navigateur.']};$('#page-title').textContent=names[page][0];$('#crumb').textContent=names[page][0];$('#page-subtitle').textContent=names[page][1];if(page==='editor'){renderEditor();setTimeout(fitZoom,60)}if(page==='candidates')renderCandidates();if(page==='templates')renderTemplateList();if(page==='overview')renderStats();}
function fabricTextValue(field){return field.source==='custom'?(field.sample||'النص الجديد'):(candidateValue(field,previewCandidate())||(state.previewId==='example'?cleanString(field.sample):''))}
