function updateFabricButton(){const button=$('#btn-fabric-mode');if(!button)return;button.classList.toggle('active',fabricMode);button.textContent=fabricMode?'Mode classique':'Canvas avancé';button.title=fabricMode?'Revenir à l’éditeur classique':'Activer les contrôles avancés Fabric.js'}
async function toggleFabricMode(enabled,{silent=false}={}){if(enabled===fabricMode&&(!enabled||fabricCanvas))return;if(enabled&&!await initFabricEditor())return;fabricMode=enabled;fabricPreferred=enabled;persist();$('#sheet').classList.toggle('fabric-mode',fabricMode);$('#field-layer').classList.toggle('hidden',fabricMode);updateFabricButton();if(fabricMode)renderFabricLayer();else if(fabricCanvas){fabricCanvas.dispose();fabricHost?.remove();fabricCanvas=null;fabricHost=null;renderFieldLayer()}if(!silent)showToast(fabricMode?'Mode canvas avancé activé':'Mode éditeur classique activé')}
function bindFabricEditor(){const toolbar=$('.canvas-toolbar .tool-set');if(!toolbar||$('#btn-fabric-mode'))return;const separator=document.createElement('span');separator.className='toolbar-separator';const button=document.createElement('button');button.id='btn-fabric-mode';button.className='tool-toggle';button.onclick=()=>{void toggleFabricMode(!fabricMode)};toolbar.append(separator,button);updateFabricButton();if(fabricPreferred)void toggleFabricMode(true,{silent:true})}
function getLayout(){return state.layouts[state.belt]??[]}
function getField(id){return getLayout().find(f=>f.id===id)}
function previewCandidate(){return state.candidates.find(c=>c.id===state.previewId)||SAMPLE}
function candidateValue(field,candidate){
 if(field.source==='custom')return cleanString(field.sample);
 if(!candidate)return cleanString(field.sample||SAMPLE[field.source]);
 if(field.source==='kyu')return candidate.kyu?`${candidate.kyu}ème Kyu`:'';
 if(field.source==='serial')return officialSerial(candidate.serial)||officialSerial(candidate.ordinal);
 return cleanString(candidate[field.source]);
}
function beltOptionHtml(selected){return BELTS.map(b=>`<option value="${html(b.id)}" ${b.id===selected?'selected':''}>${html(b.id)}</option>`).join('')}
function renderBeltSelectors(){for(const id of ['#editor-belt','#candidate-belt']){const node=$(id);if(!node)continue;node.innerHTML=(id==='#candidate-belt'?'<option value="all">Toutes les ceintures</option>':'')+beltOptionHtml(id==='#editor-belt'?state.belt:state.filterBelt)}$('#editor-belt-dot').style.background=backgroundBelt(state.belt);$('#editor-kyu').textContent=beltOf(state.belt)?.kyu?'9ème Kyu':'Kyu à confirmer';}
function selectBelt(belt){if(!beltOf(belt))return;state.belt=belt;state.selected=getLayout()[0]?.id??null;state.undo=[];state.redo=[];state.previewId=state.candidates.find(c=>c.belt===belt)?.id||'example';persist();renderEditor();setTimeout(fitZoom,20)}
function selectField(id){if(!getField(id))return;state.selected=id;renderZoneList();renderInspector();if(fabricMode&&fabricCanvas){const object=fabricCanvas.getObjects().find(item=>item.fieldId===id);if(object){fabricCanvas.setActiveObject(object);fabricCanvas.requestRenderAll()}}else renderFieldLayer()}
function trackHistory(){state.undo.push({belt:state.belt,layout:deep(getLayout())});if(state.undo.length>60)state.undo.shift();state.redo=[]}
function undo(){const entry=state.undo.pop();if(!entry)return;state.redo.push({belt:entry.belt,layout:deep(state.layouts[entry.belt])});state.layouts[entry.belt]=entry.layout;state.belt=entry.belt;state.selected=getLayout()[0]?.id??null;persist();renderEditor()}
function redo(){const entry=state.redo.pop();if(!entry)return;state.undo.push({belt:entry.belt,layout:deep(state.layouts[entry.belt])});state.layouts[entry.belt]=entry.layout;state.belt=entry.belt;state.selected=getLayout()[0]?.id??null;persist();renderEditor()}
function updateField(id,props,push=true){const field=getField(id);if(!field)return;if(push)trackHistory();Object.assign(field,props);field.x=clamp(Number(field.x),0,W);field.y=clamp(Number(field.y),0,H);field.w=clamp(Number(field.w),25,W);field.h=clamp(Number(field.h),16,H);field.size=clamp(Number(field.size),8,96);field.opacity=clamp(Number(field.opacity),0,1);field.letterSpacing=clamp(Number(field.letterSpacing||0),-3,18);field.brightness=clamp(Number(field.brightness??100),50,200);field.glow=clamp(Number(field.glow??0),0,100);field.shadow=clamp(Number(field.shadow??0),0,100);field.autoFit=field.autoFit!==false;persist();renderFieldLayer();renderZoneList()}
function updateAndInspector(id,props,push=true){updateField(id,props,push);renderInspector()}
function renderEditor(){renderBeltSelectors();renderPreviewCandidates();renderZoneList();renderInspector();renderFieldLayer();renderTemplate();$('#btn-grid').classList.toggle('active',state.grid);$('#btn-snap').classList.toggle('active',state.snap);$('#btn-guides').classList.toggle('active',state.guides);$('#sheet').classList.toggle('show-grid',state.grid);$('#sheet').classList.toggle('show-guides',state.guides);$('#zoom-label').textContent=`${Math.round(state.zoom*100)}%`}
