 const groupsHtml=groups.map((g,i)=>`<div class="import-item"><div><strong>▧ ${html(g.file)}</strong><small>${html(g.sheet)} · ${g.candidates.length} fiche(s) · ${g.declaredCount??'—'} places prévues</small></div><label>Ceinture du groupe<select data-import-belt="${i}"><option value="">Choisir la ceinture</option>${beltOptionHtml(g.belt)}</select></label><label>Date d’examen<input data-import-date="${i}" value="${html(g.examDate)}" dir="auto"></label></div>`).join('');
