async function generateExport(){
 if(state.processing)return;
 const scope=$('input[name="export-scope"]:checked')?.value,mode=$('input[name="export-mode"]:checked')?.value;
 const list=scope==='selected'?selectedCandidates():scope==='filtered'?filteredCandidates():scope==='belt'?state.candidates.filter(c=>c.belt===state.belt):state.candidates;
 if(!list.length){showToast('Aucun candidat sélectionné pour cet export.',true);return}
 const issues=[];for(const c of list){const errors=candidateErrors(c);if(errors.length)issues.push(`${c.name||'Sans nom'} : ${errors.join(', ')}`)}
 if(issues.length){$('#export-progress').innerHTML=`<div class="modal-alert">⚠ ${html(issues.slice(0,5).join(' · '))}${issues.length>5?` · +${issues.length-5} autre(s)`:''}</div>`;showToast('Export bloqué : corrigez uniquement les fiches à exporter',true);return}
 state.processing=true;const button=$('#export-confirm');button.disabled=true;button.textContent='Préparation...';const progress=$('#export-progress');
 try{
  progress.textContent='Vérification des polices…';await ensureFonts();const missing=checkFonts(list);
  if(missing.length){progress.innerHTML=`<div class="modal-alert">⚠ ${html(missing.join(' · '))}. Importez la police localement dans l’éditeur ou connectez-vous à Internet.</div>`;return}
  const sorted=[...list].sort((a,b)=>BELTS.findIndex(v=>v.id===a.belt)-BELTS.findIndex(v=>v.id===b.belt));
  const date=new Date().toISOString().slice(0,10),zip=mode==='pdf'?null:new JSZip();let done=0;
  let groups;
  if(mode==='individual') groups=Object.fromEntries(sorted.map((c,i)=>[`${String(i+1).padStart(4,'0')}_${c.id}`,[c]]));
  else if(mode==='zip') groups=sorted.reduce((o,c)=>{(o[c.belt]??=[]).push(c);return o},{});
  else groups={all:sorted};
  for(const [group,people] of Object.entries(groups)){
   const pages=[];
   for(const c of people){progress.textContent=`Diplôme ${++done} / ${sorted.length} — ${c.name}`;await new Promise(requestAnimationFrame);pages.push(await renderPdfCandidate(c))}
   const pdf=new PDFBuilder().build(pages);
   if(zip){const slug=(mode==='individual'?`${people[0].serial}_${people[0].name}`:group).replace(/[^\p{L}\p{N}_-]+/gu,'_').slice(0,80);zip.file(`Diplome_${slug}.pdf`,pdf)}
   else downloadBlob(pdf,`Diplomes_BUDO_${date}.pdf`);
  }
  if(zip){progress.textContent='Création du fichier ZIP…';const result=await zip.generateAsync({type:'blob',compression:'DEFLATE',compressionOptions:{level:4}});downloadBlob(result,`Diplomes_BUDO_${mode==='individual'?'individuels':'par_ceinture'}_${date}.zip`)}
  closeModal();showToast(`${sorted.length} certificat(s) généré(s) à partir des fiches choisies`);
 }catch(e){progress.innerHTML=`<div class="modal-alert">Erreur : ${html(e.message)}</div>`;showToast('PDF impossible : '+e.message,true)}
 finally{state.processing=false;button.disabled=false;button.textContent='Générer maintenant'}
}
