 async function deleteCustomBelt(beltId){
  const belt=beltOf(beltId);if(!belt?.custom)return;
  if(state.candidates.some(candidate=>candidate.belt===beltId)){showToast('Cette ceinture est utilisée par des candidats. Changez leur ceinture avant de la supprimer.',true);return}
  if(!await askConfirm(`Supprimer la ceinture personnalisée « ${beltId} » et sa mise en page ?`,{title:'Supprimer la ceinture',confirmLabel:'Supprimer',danger:true}))return;
  const presetId=backendPresetIds.get(beltId);
  try{if(presetId&&backendReady){try{await backendRequest(`/templates/presets/${presetId}`,{method:'DELETE'})}catch(error){if(error.status!==404)throw error}}
   BELTS=BELTS.filter(item=>item.id!==beltId);delete state.layouts[beltId];delete state.templates[beltId];backendPresetIds.delete(beltId);backendPresetFingerprints.delete(beltId);if(state.belt===beltId){state.belt=BUILTIN_BELTS.find(item=>item.id==='أصفر')?.id||BUILTIN_BELTS[0].id;state.selected=getLayout()[0]?.id||null}persist();renderBeltSelectors();renderTemplateList();renderEditor();showToast('Ceinture personnalisée supprimée')
  }catch(error){showToast(`Suppression impossible : ${error.message}`,true)}
 }
 function createBeltDialog(){
  openModal(`<div class="modal-head"><div><h2>Créer une ceinture personnalisée</h2><p>Chaque ceinture créée possède sa propre couleur, son grade, ses zones et son fond de diplôme.</p></div><button class="modal-x">×</button></div><div class="candidate-edit"><label class="wide">Nom de la ceinture<input id="new-belt-name" value="Violet" maxlength="100" placeholder="Ex. Violet ou Niveau avancé"></label><label>Couleur principale<input type="color" id="new-belt-primary" value="#7b61a8"></label><label>Deuxième couleur (optionnelle)<input type="color" id="new-belt-secondary" value="#ffffff"></label><label>Grade / Kyu (optionnel)<input id="new-belt-kyu" maxlength="40" placeholder="Ex. 1er Dan ou 8ème Kyu"></label><label class="wide">Copier les zones de<select id="new-belt-copy"><option value="blank">Mise en page vierge</option>${BELTS.map(b=>`<option value="${html(b.id)}" ${b.id==='أصفر'?'selected':''}>${html(b.id)}</option>`).join('')}</select></label></div><div class="modal-alert">Après création, importez le fond PNG/JPG/PDF, ajoutez vos zones, changez les couleurs et enregistrez. La configuration sera synchronisée avec Supabase.</div><div class="modal-footer"><button class="btn secondary" id="new-belt-cancel">Annuler</button><button class="btn primary" id="new-belt-create">Créer et éditer</button></div>`);
  $('#new-belt-cancel').onclick=closeModal;
  $('#new-belt-create').onclick=()=>{
   const name=cleanString($('#new-belt-name').value),primary=$('#new-belt-primary').value,secondary=$('#new-belt-secondary').value,copyFrom=$('#new-belt-copy').value;
   if(!name){showToast('Donnez un nom à la ceinture.',true);return}
   if(beltOf(name)){showToast('Cette ceinture existe déjà.',true);return}
   const belt=registerCustomBelt({id:name,swatches:secondary.toLowerCase()===primary.toLowerCase()?[primary]:[primary,secondary],kyu:cleanString($('#new-belt-kyu').value)||null});
   state.layouts[belt.id]=$('#new-belt-copy').value==='blank'?deep(DEFAULT_FIELDS):deep(state.layouts[copyFrom]||DEFAULT_FIELDS);state.belt=belt.id;state.selected=getLayout()[0]?.id||null;state.previewId=state.candidates.find(candidate=>candidate.belt===belt.id)?.id||'example';persist();closeModal();renderTemplateList();setPage('editor');showToast(`Ceinture « ${belt.id} » créée — importez maintenant son fond`);
  };
 }
 function createTemplateDialog(){
  openModal(`<div class="modal-head"><div><h2>Créer un modèle</h2><p>Choisissez une ceinture, donnez un nom au modèle et commencez avec une mise en page vierge ou copiée.</p></div><button class="modal-x">×</button></div><div class="candidate-edit"><label>Ceinture<select id="new-template-belt">${beltOptionHtml(state.belt)}</select></label><label>Nom du modèle<input id="new-template-name" value="Modèle personnalisé" maxlength="160"></label><label class="wide">Copier la mise en page de<select id="new-template-copy"><option value="blank">Mise en page vierge</option>${BELTS.filter(b=>b.id!==state.belt).map(b=>`<option value="${html(b.id)}" ${b.id==='أصفر'?'selected':''}>${html(b.id)}</option>`).join('')}</select></label></div><div class="modal-alert">Après création, utilisez « ＋ Nouvelle zone » ou double-cliquez sur l’aperçu pour ajouter autant de champs que nécessaire.</div><div class="modal-footer"><button class="btn secondary" id="new-template-cancel">Annuler</button><button class="btn primary" id="new-template-create">Créer et éditer</button></div>`);
  $('#new-template-cancel').onclick=closeModal;
  $('#new-template-create').onclick=()=>{
   const belt=$('#new-template-belt').value,source=$('#new-template-copy').value;
   state.layouts[belt]=source==='blank'?deep(DEFAULT_FIELDS):deep(state.layouts[source]||DEFAULT_FIELDS);
   if(state.templates[belt])state.templates[belt]={...state.templates[belt],name:$('#new-template-name').value.trim()||'Modèle personnalisé'};
   state.belt=belt;state.selected=getLayout()[0]?.id||null;state.previewId=state.candidates.find(c=>c.belt===belt)?.id||'example';
   persist();closeModal();setPage('editor');showToast(`Modèle ${belt} créé — ajoutez et placez vos zones`);
  };
 }
 function bindTemplateCreation(){
  const heading=$('#view-templates .row-heading');
  if(!heading||$('#btn-create-template'))return;
  const button=document.createElement('button');button.id='btn-create-template';button.className='btn primary small';button.textContent='＋ Créer un modèle';button.onclick=createTemplateDialog;heading.append(button);
  const beltButton=document.createElement('button');beltButton.id='btn-create-belt';beltButton.className='btn secondary small';beltButton.textContent='＋ Créer une ceinture';beltButton.onclick=createBeltDialog;heading.append(beltButton);
 }
 async function deleteCandidatesImmediately(ids,confirmBulk=false){
  const unique=[...new Set(ids)].filter(Boolean);
  if(!unique.length){showToast('Aucune fiche sélectionnée.',true);return}
  if(confirmBulk&&!await askConfirm(`Supprimer ${unique.length} fiche(s) définitivement ?`))return;
  unique.forEach(id=>backendDeletedCandidateIds.add(id));
   const remoteIds=unique.filter(id=>state.candidates.some(candidate=>candidate.id===id&&!candidate.demo));
  debugLog('Candidate delete requested', {ids:unique,remoteIds});
  try{
    for(const id of remoteIds){try{await backendRequest(`/candidates/${id}`,{method:'DELETE'})}catch(error){if(error.status!==404)throw error}}
  }catch(error){unique.forEach(id=>{if(state.candidates.some(candidate=>candidate.id===id))backendDeletedCandidateIds.delete(id)});showToast(`Suppression impossible : ${error.message}`,true);return}
  remoteIds.forEach(id=>backendCandidateIds.delete(id));
  state.candidates=state.candidates.filter(candidate=>!unique.includes(candidate.id));
  unique.forEach(id=>state.selectedIds.delete(id));
  persist();renderCandidates();renderStats();showToast(`${unique.length} fiche(s) supprimée(s)`);
  debugLog('Candidate delete completed', {ids:unique});
 }
 function bindImmediateDeletion(){
  document.addEventListener('click',event=>{
   const single=event.target.closest('[data-delete]');
   const bulk=event.target.closest('#btn-delete-selected');
   if(!single&&!bulk)return;
   event.preventDefault();event.stopImmediatePropagation();
   if(single)deleteCandidatesImmediately([single.dataset.delete]);
   else deleteCandidatesImmediately([...state.selectedIds],true);
  },true);
 }
 async function start(){tryLoadSettings();bindGlobal();bindImmediateDeletion();bindTemplateCreation();bindBackendTools();renderBeltSelectors();renderStats();renderEditor();setPage('editor');await restoreFont();await restoreImages();renderTemplateList();await new Promise(r=>setTimeout(r,130));fitZoom();await initBackend();}
start().catch(e=>{console.error('Échec BUDO Studio',e);showToast('Application non initialisée : '+e.message,true)});
